package cn.xiaoyanjiu.ff14chat;
public final class RisingStonesNavigationRegression {
 static int checks;static void check(boolean b,String label){if(!b)throw new AssertionError(label);checks++;System.out.println("PASS "+label);}
 public static void main(String[] args){check(RisingStonesNavigation.allowed("https://ff14risingstones.web.sdo.com/pc/index.html#/post"),"community page stays in app");check(RisingStonesNavigation.allowed("https://passport.sdo.com/login?redirect=https%3A%2F%2Fff14risingstones.web.sdo.com"),"SSO redirects remain internal");check(RisingStonesNavigation.allowed("https://login.sdg-china.com/login"),"cross-domain HTTPS login does not launch browser");check(RisingStonesNavigation.allowed("https://auth.example.test/callback?code=fixture"),"HTTPS authorization callback is retained");check(RisingStonesNavigation.allowed("HTTPS://example.test/login"),"scheme case accepted");check(!RisingStonesNavigation.allowed("javascript:alert(1)"),"javascript URL not navigated");check(!RisingStonesNavigation.allowed("file:///sdcard/private.txt"),"file navigation rejected");check(!RisingStonesNavigation.allowed("https://user:password@example.test"),"credentials in URL authority rejected");check(!RisingStonesNavigation.allowed("http://example.test/login"),"cleartext login not silently permitted");check(!RisingStonesNavigation.allowed(null),"invalid URL rejected");check(RisingStonesNavigation.allowed("https://api.rail.tgp.qq.com/web/oauth2.0/authorize?scope=openid%20profile&state=fixture|mobile"),"OAuth state query accepted like browser");check(RisingStonesNavigation.allowed("https://api.rail.tgp.qq.com/web/oauth2.0/authorize?state={fixture}"),"browser-valid callback state does not fail strict URI parsing");check(!RisingStonesNavigation.allowed("https://example.test/\r\nHeader:value"),"control characters rejected");check("https://api.rail.tgp.qq.com/web/oauth2.0/authorize?state=fixture%7Cmobile&redirect_uri=http%3A%2F%2Fexample.test%2Fcb#keep".equals(RisingStonesNavigation.upgradeHttp("http://api.rail.tgp.qq.com/web/oauth2.0/authorize?state=fixture%7Cmobile&redirect_uri=http%3A%2F%2Fexample.test%2Fcb#keep")),"upgrade preserves encoded OAuth query, nested callback and fragment");check("https://example.test/cb?code=fixture".equals(RisingStonesNavigation.upgradeHttp("http://example.test:80/cb?code=fixture")),"explicit HTTP default port upgrades to HTTPS default");check(RisingStonesNavigation.upgradeHttp("http://user:password@example.test/")==null,"upgrade rejects URL credentials");check(RisingStonesNavigation.upgradeHttp("http://example.test:8080/cb")==null,"upgrade does not retarget arbitrary service ports");check(RisingStonesNavigation.upgradeHttp("https://example.test/cb")==null,"HTTPS does not loop through upgrade");System.out.println(checks+" navigation checks passed; no account login performed.");}
}

